    ["An ESO addon cannot read Windows Task Scheduler or the external backup directory. This is not a claim that the helper is healthy.\nUse the Windows task 'Crown Crate Codex History Backup' and .local/history-backups to check it.\nNo per-frame addon update or repeating import timer is registered."] = "Аддон ESO не читает планировщик Windows и внешний каталог копий. Это не подтверждение исправности программы.\nПроверьте задачу 'Crown Crate Codex History Backup' и .local/history-backups.\nНет обновления на каждом кадре и повторяющегося таймера импорта.",
    ["Crown Crate Codex: switch to keyboard mode to open Controls > Keybindings."] = "Crown Crate Codex: переключитесь в режим клавиатуры для настройки клавиш.",
    ["Crown Crate Codex: keybindings opened. Find the Crown Crate Codex category."] = "Crown Crate Codex: настройки клавиш открыты. Найдите раздел Crown Crate Codex.",
    ["Crown Crate Codex: open Controls > Keybindings and find Crown Crate Codex."] = "Crown Crate Codex: откройте настройки клавиш и найдите Crown Crate Codex.",
    ["Crown Crate Codex: install/enable LibAddonMenu-2.0 for Settings > AddOns. Display controls and /ccc keys still work."] = "Crown Crate Codex: включите LibAddonMenu-2.0 для настроек аддонов. Элементы интерфейса и /ccc keys работают и без него.",
    ["Crown Crate Codex: this client cannot open that collectible directly."] = "Crown Crate Codex: клиент не может открыть этот коллекционный предмет напрямую.",
    ["Crown Crate Codex: history profiles are not ready. Reload the UI and try again."] = "Crown Crate Codex: профили истории не готовы. Перезагрузите интерфейс и повторите.",
    ["Crown Crate Codex: could not open the import dialog: "] = "Crown Crate Codex: не удалось открыть окно импорта: ",
    ["Crown Crate Codex: %d imported into %s, %d already present, %d skipped because they exist on another server."] = "Crown Crate Codex: %d импортировано на %s, %d уже есть, %d пропущено из-за наличия на другом сервере.",
    ["Crown Crate Codex: imported %d Tracker openings. Original history unchanged."] = "Crown Crate Codex: импортировано %d открытий Tracker. Исходная история не изменена.",
    ["Crown Crate Codex: could not read this opening. Use /ccc status for diagnostics."] = "Crown Crate Codex: не удалось прочитать открытие. Диагностика: /ccc status.",
    ["Crown Crate Codex: refreshed owned and on-sale crate types."] = "Crown Crate Codex: обновлены имеющиеся и продаваемые типы ящиков.",
    ["Crown Crate Codex %s | API %s | %d openings | %d failed requests | %d unreadable openings"] = "Crown Crate Codex %s | API %s | %d открытий | %d сбоев | %d нечитаемых",
    ["Tracker sync: %d added, %d existing, %d unreadable | Imported statistics: %s | Imported tier rates: %s"] = "Синхронизация Tracker: %d добавлено, %d уже есть, %d нечитаемых | Импорт статистики: %s | Импорт уровней: %s",
    ["Next part"] = "Следующая часть",
    ["Copy CSV | Part %d of %d"] = "Копировать CSV | Часть %d из %d",
    ["Ctrl+A, Ctrl+C to copy. Append every part in order to one UTF-8 CSV file.\nExport follows History's search and crate filter."] = "Ctrl+A, Ctrl+C для копирования. Добавьте все части по порядку в один CSV-файл UTF-8.\nЭкспорт учитывает поиск и фильтр ящиков истории.",
}
